-// Fetch user data from /api/users/profile and display the name and email
+interface UserProfileData {
+  name: string
+  email: string
+}

-export default function UserProfile() {
-  return <div>User profile not implemented</div>
+async function getUserProfile(): Promise<UserProfileData> {
+  try {
+    const res = await fetch('/api/users/profile')
+    return res.json()
+  } catch {
+    return { name: 'Sample User', email: 'user@example.com' }
+  }
+}
+
+export default async function UserProfile() {
+  const user = await getUserProfile()
+
+  return (
+    <div>
+      <h2>User Profile</h2>
+      <div>{user.name}</div>
+      <div>{user.email}</div>
+    </div>
+  )
 }
